"""Original Python fundamentals and language micro-labs."""
from python_guide_topics import add

def t(stage,key,title,meaning,trap,body,cases,old,new,imports=''):
    add(stage,key,title,meaning,trap,body,cases,(old,new),imports)

# Each computation has a contract, multiple examples and a specific incorrect alternative.
t(1,'name-rebinding','Names and rebinding','Assignment binds a name to an object. Rebinding one name does not change another name that referred to the old immutable value.','Rebinding an integer name is not mutation of a shared integer.','a = data\nb = a\na += 1\nresult = [a,b]',[(3,[4,3]),(-1,[0,-1])],'[a,b]','[a,a]')
t(1,'integer-division','Integer division and remainder','For a positive divisor, // gives the floor quotient and % gives a nonnegative remainder. Together they reconstruct the dividend, including negative dividends.','Truncation toward zero differs from floor division for negative values.','q,r = divmod(data[0],data[1])\nresult = [q,r,q*data[1]+r]',[([7,3],[2,1,7]),([-7,3],[-3,2,-7])],'divmod(data[0],data[1])','(int(data[0]/data[1]), data[0]%data[1])')
t(1,'float-tolerance','Floating point comparisons','Binary floating point approximates many decimal fractions. Compare measured results with justified tolerances rather than requiring exact equality.','Exact equality can reject a numerically acceptable floating result.','result = math.isclose(sum(data),0.3,rel_tol=1e-9,abs_tol=1e-12)',[([0.1,0.2],True),([0.1,0.1],False)],'math.isclose(sum(data),0.3,rel_tol=1e-9,abs_tol=1e-12)','sum(data)==0.3','import math')
t(1,'explicit-conversion','Convert text at a boundary','Text from a user or file is not automatically numeric. Parse it at the input boundary before arithmetic, and handle invalid text as a separate failure.','Adding numeric strings concatenates rather than adds their numeric values.','result = int(data[0])+int(data[1])',[(['12','3'],15),(['-2','5'],3)],'int(data[0])+int(data[1])','data[0]+data[1]')
t(1,'string-index','Index strings carefully','A Python string is a sequence of Unicode code points. A negative index counts from the end; these are not UTF-8 byte offsets or necessarily displayed grapheme clusters.','The first character and last character are different positions.','result = [data[0],data[-1],len(data)]',[('cat',['c','t',3]),('éx',['é','x',2])],'data[-1]','data[0]')
t(1,'format-values','Format values for people','An f-string evaluates expressions and applies formatting. A precision specifier changes the displayed representation without changing the underlying floating value.','String conversion alone does not guarantee a fixed number of decimal places.',"result = f'{data:.2f}'",[(2.5,'2.50'),(-1.125,'-1.12')],"f'{data:.2f}'",'str(data)')
t(1,'boolean-comparison','Comparisons return booleans','A comparison produces True or False. Chained comparisons express an interval and evaluate the middle expression once.','An inclusive upper limit admits a boundary excluded by a half-open interval.','result = 0 <= data < 10',[(0,True),(10,False),(-1,False)],'data < 10','data <= 10')
t(1,'none-sentinel','None is a sentinel','None denotes absence. Test identity with is None so zero, False and empty containers remain legitimate values.','Truthiness conflates absence with valid falsy values.',"result = 'missing' if data is None else 'present'",[(None,'missing'),(0,'present'),([], 'present')],'data is None','not data')
t(1,'list-first','Lists hold ordered values','A list preserves element order and permits indexed access. Check emptiness before accessing the first element; an empty collection is a normal boundary case.','Indexing without an emptiness guard raises on an empty list.','result = data[0] if data else None',[([7,8],7),([],None)],'data[0] if data else None','data[0]')
t(1,'error-location','Read exception types','Exceptions describe failed operations. Catch the specific parsing error at the boundary and leave unrelated programming errors visible.','Returning a default for every input hides whether parsing actually succeeded.',"try:\n    result = int(data)\nexcept ValueError:\n    result = None",[('42',42),('oops',None)],'int(data)','0')

t(2,'branch-order','Order conditional branches','An if/elif chain chooses its first true branch. Test the most restrictive category first so a broader condition does not shadow it.','Testing the lower threshold first misclassifies values in the higher category.',"result = 'high' if data >= 10 else 'mid' if data >= 5 else 'low'",[(12,'high'),(7,'mid'),(2,'low')],'data >= 10','data >= 20')
t(2,'range-stop','Half-open ranges','range(start, stop) excludes stop. This makes lengths and adjacent intervals compose without counting a boundary twice.','Including the stop value changes the range length.','result = list(range(data))',[(3,[0,1,2]),(0,[])],'range(data)','range(data+1)')
t(2,'loop-accumulator','Accumulate in a loop','Initialize the accumulator once, update it for every item, and return it after traversal. The initial value defines what happens on empty input.','Resetting or ignoring the accumulator loses earlier terms.','total = 0\nfor x in data:\n    total += x\nresult = total',[([2,3,4],9),([],0)],'total += x','total = x')
t(2,'break-search','Stop at the first match','break terminates the nearest loop. A sentinel result lets a search distinguish a found value from the absence of any match.','Continuing after a match returns the last match rather than the first.','result = None\nfor x in data:\n    if x > 0:\n        result = x\n        break',[([-1,2,3],2),([-2,0],None)],'        break','        pass')
t(2,'continue-filter','Skip rejected elements','continue skips the rest of the current iteration. Put the rejection condition before any state update that should apply only to accepted elements.','Counting rejected elements violates the filter predicate.','result = []\nfor x in data:\n    if x < 0:\n        continue\n    result.append(x)',[([-1,0,2],[0,2]),([-3],[])],'        continue','        pass')
t(2,'loop-else','Understand loop else','A loop else runs when the loop finishes without break, including an empty traversal. It can express failure of an early-exit search.','An unconditional final assignment overwrites the successful search.','result = False\nfor x in data:\n    if x == 7:\n        result = True\n        break\nelse:\n    result = False',[([1,7],True),([],False)],'result = True','result = False')
t(2,'short-circuit','Short circuit unsafe operations','and evaluates its right operand only when its left operand is truthy. A denominator guard prevents division by zero before comparison.','Reversing the guard evaluates unsafe division first.','result = data != 0 and 10/data > 2',[(0,False),(2,True),(5,False)],'data != 0 and 10/data > 2','10/data > 2 and data != 0')
t(2,'enumerate-offset','Enumerate index and value','enumerate supplies a counter alongside each value. Its start argument controls the labels without changing the input collection.','A zero-based label is wrong when the output contract is one-based.','result = [[i,x] for i,x in enumerate(data,start=1)]',[(['a','b'],[[1,'a'],[2,'b']]),([],[])],'start=1','start=0')
t(2,'zip-length','Zip and length contracts','zip stops at the shortest input by default. Use strict=True when unequal lengths indicate invalid paired records.','Silently truncating pairs discards unpaired data.','try:\n    result = [list(p) for p in zip(*data,strict=True)]\nexcept ValueError:\n    result = None',[([[1,2],[3,4]],[[1,3],[2,4]]),([[1,2],[3]],None)],'strict=True','strict=False')
t(2,'unicode-normalize','Normalize Unicode intentionally','Visually similar text may use different code-point sequences. NFC normalization combines canonical equivalents before equality comparison.','Raw code-point equality can disagree with canonical equivalence.',"result = unicodedata.normalize('NFC',data[0]) == unicodedata.normalize('NFC',data[1])",[(['é','e\u0301'],True),(['a','b'],False)],"unicodedata.normalize('NFC',data[0]) == unicodedata.normalize('NFC',data[1])",'data[0] == data[1]','import unicodedata')
t(2,'bytes-encoding','Separate bytes from text','Encoding turns text into bytes using an explicit codec. UTF-8 uses a variable number of bytes per code point, so byte length and string length differ.','Counting characters is not a UTF-8 payload byte count.',"result = len(data.encode('utf-8'))",[('cat',3),('é',2)],"len(data.encode('utf-8'))",'len(data)')

t(3,'slicing-step','Slice with a step','A slice selects a subsequence without mutating the original list. A negative step walks backward, while the stop remains exclusive.','Reversing the input in place changes shared state.','result = data[::-1]',[([1,2,3],[3,2,1]),([],[])],'data[::-1]','data[:]')
t(3,'nested-copy','Copy nested mutable structures','A shallow copy duplicates the outer list while nested mutable objects stay shared. deepcopy is appropriate when independent nested state is the required contract.','Copying only the outer container still shares inner lists.','other = copy.deepcopy(data)\nother[0].append(9)\nresult = data',[([[1],[2]],[[1],[2]]),([[]],[[]])],'copy.deepcopy(data)','data.copy()','import copy')
t(3,'dict-counts','Count with dictionaries','Dictionary lookup associates a hashable key with a value. get supplies the initial count only when the key is absent, then repeated keys increment it.','Overwriting with one loses occurrence counts.','counts = {}\nfor x in data:\n    counts[x] = counts.get(x,0)+1\nresult = counts',[(['a','b','a'],{'a':2,'b':1}),([], {})],'counts.get(x,0)+1','1')
t(3,'set-membership','Deduplicate with sets','A set represents distinct hashable values and supports membership. Sort the distinct values when a deterministic output order is part of the contract.','A sorted list alone retains duplicates.','result = sorted(set(data))',[([3,1,3],[1,3]),([],[])],'sorted(set(data))','sorted(data)')
t(3,'stable-sort','Stable sorting and keys','Python sorting is stable: equal keys preserve their input order. A key function controls ordering without changing the records themselves.','Sorting on the wrong field changes the intended ranking.','result = sorted(data,key=lambda row:row[1])',[([['b',2],['a',1],['c',1]],[['a',1],['c',1],['b',2]]),([],[])],'row[1]','row[0]')
t(3,'comprehension-filter','Comprehensions combine map and filter','A comprehension first selects each input satisfying its condition, then computes an output expression. Filtering and transforming are separate parts of the contract.','Squaring rejected negative values includes records meant to be removed.','result = [x*x for x in data if x >= 0]',[([-2,0,3],[0,9]),([],[])],'if x >= 0','if True')
t(3,'deque-queue','Queues need efficient end operations','deque supports appending at one end and removing from the other without shifting every remaining element. FIFO removes the oldest item.','Popping from the insertion end implements a stack instead.','queue = deque(data)\nresult = queue.popleft() if queue else None',[([1,2,3],1),([],None)],'queue.popleft()','queue.pop()','from collections import deque')
t(3,'heap-smallest','Maintain a min heap','A min heap exposes the smallest value at its root. heapify establishes the invariant; heap order does not mean every array position is globally sorted.','Reading the first unsorted input element is not a minimum operation.','items = list(data)\nheapq.heapify(items)\nresult = heapq.heappop(items) if items else None',[([4,1,3],1),([],None)],'heapq.heapify(items)','pass','import heapq')
t(3,'binary-search','Binary search needs sorted data','bisect_left returns the first insertion position preserving sorted order. Check both the bound and equality when using that position for membership.','An insertion position can exist even when the target is absent.','items,target = data\ni = bisect.bisect_left(items,target)\nresult = i < len(items) and items[i] == target',[([[1,3,5],3],True),([[1,3,5],2],False),([[],1],False)],'i < len(items) and items[i] == target','i < len(items)','import bisect')
t(3,'hash-equality','Equality and hashing agree','Equal immutable tuples must have equal hashes. Hash equality alone cannot prove value equality because hash functions may collide.','Identity is not a substitute for structural value equality.','a = tuple(data)\nb = tuple(list(data))\nresult = [a==b,hash(a)==hash(b)]',[([1,2],[True,True]),([3],[True,True])],'a==b','a is b')
t(3,'linear-prefix','Prefix sums avoid repeated work','A prefix sum records the total through each position. One traversal maintains a running total rather than recomputing every prefix from scratch.','Emitting the unaccumulated values does not produce prefix totals.','result = list(itertools.accumulate(data))',[([2,3,4],[2,5,9]),([],[])],'itertools.accumulate(data)','iter(data)','import itertools')

t(4,'function-return','Return values explicitly','A function call evaluates its body and returns a value to its caller. Falling off the end returns None; printing a value is a separate side effect.','Computing a value without returning it loses the function result.','def double(x):\n    return x*2\nresult = double(data)',[(4,8),(-2,-4)],'return x*2','x*2')
t(4,'default-factory','Avoid mutable default state','Default argument objects are created at function definition. Use None and allocate inside the call when each invocation needs an independent list.','A shared default list carries values from earlier calls.','def collect(x,items=None):\n    if items is None:\n        items = []\n    items.append(x)\n    return items\na = collect(data[0])\nb = collect(data[1])\nresult = [a,b]',[([1,2],[[1],[2]]),([0,0],[[0],[0]])],'items=None','items=[]')
t(4,'keyword-only','Keyword-only API boundaries','A parameter after * must be passed by name. This prevents ambiguous positional configuration and produces TypeError for a positional call.','Removing * permits a call the public contract rejects.','def scale(x,*,factor):\n    return x*factor\ntry:\n    result = scale(*data)\nexcept TypeError:\n    result = "keyword required"',[([2,3],'keyword required'),([1,4],'keyword required')],'x,*,factor','x,factor')
t(4,'positional-only','Positional-only parameters','A slash marks parameters that callers must supply positionally. This lets implementations rename internal parameter names without supporting those names as public keywords.','Removing the slash changes which keyword calls are accepted.','def f(value,/):\n    return value\ntry:\n    result = f(value=data)\nexcept TypeError:\n    result = "positional required"',[(3,'positional required'),(0,'positional required')],'value,/','value')
t(4,'argument-unpacking','Unpack argument sequences','The * operator expands an iterable into positional arguments. It does not wrap the whole sequence as one argument.','Passing the list as one argument violates a two-argument signature.','def add_pair(a,b):\n    return a+b\nresult = add_pair(*data)',[([2,3],5),([-1,1],0)],'add_pair(*data)','add_pair(data)')
t(4,'closure-binding','Closures capture bindings','Closures look up captured names when called. A default parameter can snapshot the current loop value when constructing independent callbacks.','Late binding makes every callback observe the final loop value.','callbacks = [lambda x=x:x for x in data]\nresult = [f() for f in callbacks]',[([1,2,3],[1,2,3]),([],[])],'lambda x=x:x','lambda:x')
t(4,'nonlocal-state','Update enclosing state with nonlocal','A nested function needs nonlocal to rebind a variable in its enclosing function. The closure can then maintain state across calls.','Creating a local counter disconnects updates from the enclosing state.','def counter():\n    n = 0\n    def step():\n        nonlocal n\n        n += 1\n        return n\n    return step\nf = counter()\nresult = [f() for _ in range(data)]',[(3,[1,2,3]),(0,[])],'nonlocal n','n = 0')
t(4,'recursive-base','Recursion needs a base case','A recursive function solves a smaller subproblem and stops at a base case. For factorial on nonnegative integers, zero maps to one.','A zero base result makes every positive factorial zero.','def factorial(n):\n    return 1 if n == 0 else n*factorial(n-1)\nresult = factorial(data)',[(0,1),(5,120)],'1 if n == 0','0 if n == 0')
t(4,'module-main','Separate import from script entry','A module is executed during its first import. The __main__ guard protects script-only behavior so importing definitions does not invoke the entry point.','Running the entry point unconditionally causes import-time side effects.',"namespace = {'__name__':data,'calls':[]}\nexec(\"if __name__ == '__main__':\\n    calls.append('run')\",namespace)\nresult = namespace['calls']",[('__main__',['run']),('library',[])],"if __name__ == '__main__':",'if True:')
t(4,'functools-partial','Bind configuration with partial','partial pre-binds some function arguments while leaving others for later calls. Bind keyword configuration explicitly when it should not consume a data argument.','Changing the bound exponent changes the operation.','square = functools.partial(pow,exp=2)\nresult = square(data)',[(3,9),(0,0)],'exp=2','exp=3','import functools')
t(4,'import-discovery','Inspect modules without wildcard imports','import_module loads a module by name and returns the module object. Access a known public attribute explicitly; do not execute arbitrary untrusted module names.','Looking up a nonexistent attribute fails even when the module import succeeds.',"module = importlib.import_module('math')\nresult = getattr(module,'isfinite')(data)",[(1.5,True),(0,True)],"'isfinite'","'missing_attribute'",'import importlib')

t(5,'exception-specific','Catch expected failures narrowly','Catch ValueError for invalid integer text and let unrelated failures propagate. A fallback should represent the domain error rather than disguise it as a valid number.','Using zero for parse failure confuses invalid text with an actual zero.',"try:\n    result = int(data)\nexcept ValueError:\n    result = 'invalid'",[('0',0),('x','invalid')],"result = 'invalid'",'result = 0')
t(5,'exception-chaining','Preserve an error cause','raise NewError from original attaches the causal exception explicitly. Callers can inspect the stable outer error without losing low-level context.','Suppressing the cause erases diagnostic context.',"try:\n    try:\n        int(data)\n    except ValueError as error:\n        raise RuntimeError('bad input') from error\nexcept RuntimeError as error:\n    result = type(error.__cause__).__name__",[('x','ValueError'),('bad','ValueError')],'from error','from None')
t(5,'finally-cleanup','Cleanup runs on exceptional exits','finally executes when control leaves a try block, including after an exception. It is the place for unconditional cleanup rather than success-only bookkeeping.','Cleanup placed only on the successful path misses failures.',"events = []\ntry:\n    if data:\n        raise ValueError('stop')\nexcept ValueError:\n    events.append('error')\nfinally:\n    events.append('close')\nresult = events",[(True,['error','close']),(False,['close'])],"events.append('close')","events.append('open')")
t(5,'contextmanager','A context manager scopes a resource','The with statement enters a resource scope and exits it even when the body raises. A contextmanager generator should place its teardown in finally.','Skipping the finalizer leaves ownership work unfinished.',"events = []\n@contextmanager\ndef owned():\n    events.append('open')\n    try:\n        yield\n    finally:\n        events.append('close')\ntry:\n    with owned():\n        if data:\n            raise ValueError('stop')\nexcept ValueError:\n    pass\nresult = events",[(True,['open','close']),(False,['open','close'])],"events.append('close')","events.append('leaked')",'from contextlib import contextmanager')
t(5,'path-components','Use path APIs for paths','Path joins components according to filesystem path rules. Its name property returns the final component without assuming a fixed slash-delimited prefix length.','Returning the parent directory is not the final filename.','result = Path(data).name',[('logs/run.txt','run.txt'),('a/b.csv','b.csv')],'Path(data).name','str(Path(data).parent)','from pathlib import Path')
t(5,'text-file','Close text files deterministically','Open text with an explicit encoding and close it using with. A temporary directory isolates this trusted local example and is removed on exit.','A write of the wrong text can still exit successfully.','with tempfile.TemporaryDirectory() as directory:\n    path = Path(directory)/"sample.txt"\n    with path.open("w",encoding="utf-8") as stream:\n        stream.write(data)\n    result = path.read_text(encoding="utf-8")',[('café','café'),('','')],'stream.write(data)','stream.write(data.upper())','import tempfile\nfrom pathlib import Path')
t(5,'json-boundary','JSON preserves supported structures','JSON encodes portable data structures, not arbitrary Python object identity. Round-trip a record using its explicit schema and validate required keys at the boundary.','Stringifying a record loses its structured JSON representation.','result = json.loads(json.dumps(data))',[({'x':[1,2]},{'x':[1,2]}),([],[])],'json.dumps(data)','json.dumps(str(data))')
t(5,'csv-quoting','CSV fields can contain delimiters','A CSV parser handles quoting and escaped delimiters. Splitting on commas manually is not equivalent when fields contain commas inside quotes.','Manual comma splitting breaks quoted records.','result = next(csv.reader([data]))',[( 'a,"b,c"',['a','b,c']),('x,y',['x','y'])],'next(csv.reader([data]))',"data.split(',')",'import csv')
t(5,'aware-datetime','Time zones are part of timestamps','An aware datetime identifies an instant using its offset. Converting to UTC adjusts clock time while preserving that instant; replacing tzinfo alone does not.','Relabelling a timezone does not convert the instant.','dt = datetime.fromisoformat(data)\nresult = dt.astimezone(timezone.utc).isoformat()', [('2026-01-01T12:00:00+02:00','2026-01-01T10:00:00+00:00'),('2026-01-01T12:00:00+00:00','2026-01-01T12:00:00+00:00')],'dt.astimezone(timezone.utc)','dt.replace(tzinfo=timezone.utc)','from datetime import datetime,timezone')
t(5,'cli-arguments','Parse CLI types at the boundary','argparse converts option text according to its type specification. The result namespace should contain domain values before application logic starts.','Omitting the type leaves the value as text.','parser = argparse.ArgumentParser()\nparser.add_argument("--count",type=int)\nresult = parser.parse_args(["--count",data]).count',[('3',3),('0',0)],'type=int','type=str','import argparse')
t(5,'exception-groups','Handle related failures with except star','ExceptionGroup preserves multiple failures. except* handles matching leaves while allowing other kinds to be handled independently.','Counting only one leaf loses concurrent failure information.','try:\n    raise ExceptionGroup("batch",[ValueError(str(x)) for x in data])\nexcept* ValueError as group:\n    result = len(group.exceptions)',[([1,2],2),([3],1)],'len(group.exceptions)','1')
